<?php
$edit=null;if(isset($_GET['edit'])){$stmt=$db->prepare('SELECT * FROM classes WHERE id=?');$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch();}
$showForm=isset($_GET['create'])||$edit;
$classes=$db->query('SELECT c.*,(SELECT COUNT(*) FROM schedules s WHERE s.class_id=c.id) schedule_count FROM classes c ORDER BY c.status,c.name')->fetchAll();
?>
<div class="section-title"><div><h2>Daftar kelas</h2><p>Simpan informasi kelas, ruangan, dan jumlah siswa.</p></div><a class="btn btn-primary" href="<?= url('classes',['create'=>1]) ?>"><?= icon('plus',17) ?> Tambah</a></div>
<?php if($showForm): ?><section class="card"><div class="card-header"><div><h2><?= $edit?'Edit':'Tambah' ?> kelas</h2></div></div><div class="card-body"><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_class"><input type="hidden" name="id" value="<?= e($edit['id']??'') ?>"><div class="form-grid"><div class="form-group"><label>Nama kelas *</label><input class="form-control" name="name" required placeholder="VIII A" value="<?= e($edit['name']??'') ?>"></div><div class="form-group"><label>Jenjang atau tingkat *</label><input class="form-control" name="grade_level" required placeholder="SMP Kelas VIII" value="<?= e($edit['grade_level']??'') ?>"></div><div class="form-group"><label>Sekolah atau lembaga</label><input class="form-control" name="institution" value="<?= e($edit['institution']??'') ?>"></div><div class="form-group"><label>Ruangan</label><input class="form-control" name="room" value="<?= e($edit['room']??'') ?>"></div><div class="form-group"><label>Jumlah siswa</label><input class="form-control" type="number" min="0" name="student_count" value="<?= e((string)($edit['student_count']??0)) ?>"></div><div class="form-group"><label>Status</label><select class="form-control" name="status"><option value="active" <?= selected($edit['status']??'active','active') ?>>Aktif</option><option value="archived" <?= selected($edit['status']??'','archived') ?>>Arsip</option></select></div><div class="form-group full"><label>Catatan kelas</label><textarea class="form-control" name="notes"><?= e($edit['notes']??'') ?></textarea></div></div><div class="form-actions"><a class="btn btn-secondary" href="<?= url('classes') ?>">Batal</a><button class="btn btn-primary">Simpan kelas</button></div></form></div></section><?php endif; ?>
<section class="card mt-3"><div class="card-header"><div><h2>Semua kelas</h2><p><?= count($classes) ?> kelas tersimpan</p></div><div class="search-box"><?= icon('search',17) ?><input class="form-control" placeholder="Cari kelas..." data-filter-table="#class-table"></div></div><div class="table-wrap"><table class="data-table" id="class-table"><thead><tr><th>Kelas</th><th>Lembaga</th><th>Siswa</th><th>Jadwal</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($classes as $item): ?><tr><td><strong><?= e($item['name']) ?></strong><div class="muted text-sm"><?= e($item['grade_level']) ?><?= $item['room']?' • '.e($item['room']):'' ?></div></td><td><?= e($item['institution']?:'-') ?></td><td><?= (int)$item['student_count'] ?></td><td><?= (int)$item['schedule_count'] ?></td><td><?= status_badge($item['status']) ?></td><td><div class="actions"><a class="btn btn-secondary btn-sm" href="<?= url('classes',['edit'=>$item['id']]) ?>"><?= icon('edit',14) ?></a><form method="post" data-confirm="Hapus kelas ini?"><?= csrf_field() ?><input type="hidden" name="action" value="delete_class"><input type="hidden" name="id" value="<?= $item['id'] ?>"><button class="btn btn-danger btn-sm"><?= icon('trash',14) ?></button></form></div></td></tr><?php endforeach; ?><?php if(!$classes): ?><tr><td colspan="6"><div class="empty-state"><h3>Belum ada kelas</h3><p>Tambahkan kelas untuk membuat jadwal mengajar.</p></div></td></tr><?php endif; ?></tbody></table></div></section>
